global_scss:
// =============================================================================
//  UNIMY — Global Brand Identity (_variables.scss)
//  Single source of truth for design tokens, typography, breakpoints, mixins.
//  Page-specific component files MUST import this and never redefine tokens.
//
//  Source-of-record changes vs. previous _variable.css:
//   • $breakpoints SCSS map added (required by Directive 7)
//   • Focus-ring tokens added (Directive 8 — WCAG)
//   • Course-page tokens promoted to global (flagged with `// + course-page`)
//   • All previous tokens preserved verbatim// =============================================================================

// -----------------------------------------------------------------------------
//  1. COLOR — NEUTRALS
// -----------------------------------------------------------------------------

$c-ink:            #0B1020;
$c-ink-soft:       #1A2238;   // + course-page
$c-muted:          #5B6478;
$c-muted-2:        #6B7280;   // + course-page
$c-muted-mid:      #4B5563;   // + course-page (medium-dark gray)
$c-line:           #E6E8EE;
$c-line-strong:    #C9D3FF;
$c-line-soft:      #EEF0F5;   // + course-page
$c-bg:             #FFFFFF;
$c-bg-soft:        #F4F6FB;
$c-bg-softer:      #F8F9FC;   // + course-page (page bg)
$c-bg-lavender:    #F5F3FF;   // + course-page (callouts)

// -----------------------------------------------------------------------------
//  2. COLOR — BRAND
// -----------------------------------------------------------------------------

$c-blue:           #1F5CFF;
$c-blue-deep:      #2563EB;   // + course-page
$c-purple:         #7C3AED;
$c-purple-deep:    #6D28D9;   // + course-page
$c-purple-light:   #B5A0FF;
$c-purple-soft:    #A78BFA;
$c-purple-bg:      #EDE9FE;   // + course-page
$c-pink:           #FF2D87;
$c-red:            #E5252B;
$c-green:          #16A34A;   // + course-page
$c-amber:          #F5B100;   // + course-page

// -----------------------------------------------------------------------------
//  3. COLOR — DARK SURFACES
// -----------------------------------------------------------------------------

$c-dark:           #07091A;
$c-dark-1:         #06091F;
$c-dark-2:         #0A1230;
$c-dark-3:         #0E1838;
$c-dark-4:         #131A3D;   // + course-page (alumni)
$c-card-dark:      #16204A;
$c-card-dark-2:    #1B2658;   // + course-page (rank card)

// -----------------------------------------------------------------------------
//  4. GRADIENTS
// -----------------------------------------------------------------------------

$g-blue:           linear-gradient(90deg, #2563EB, #1F5CFF);
$g-pink:           linear-gradient(90deg, #FF2D87, #FF4FA1);
$g-hero-text:      linear-gradient(90deg, #4DA2FF 0%, #2E73FF 25%, #7C8FFF 50%, #A855F7 75%, #C084FC 100%);
$g-hero-bg:        radial-gradient(900px 500px at 75% 35%, rgba(255,46,151,.25), transparent 60%),
                   radial-gradient(800px 500px at 88% 65%, rgba(37,99,235,.45), transparent 60%),
                   linear-gradient(180deg, #07091A 0%, #0A0F2A 100%);
$g-difference:     linear-gradient(180deg, #0A1230 0%, #0E1838 100%);
$g-ai:             linear-gradient(120deg, #1A1A4A 0%, #232767 40%, #3B4E89 100%);
$g-starts:         linear-gradient(90deg, #8B5CF6 0%, #6366F1 50%, #3B82F6 100%);
// + course-page gradients
$g-hero-course:    linear-gradient(135deg, #0B0E2E 0%, #1A1F4A 50%, #2D2570 100%);
$g-purple-btn:     linear-gradient(90deg, #8B5CF6 0%, #7C3AED 100%);
$g-purple-section: linear-gradient(135deg, #8B5CF6 0%, #7C3AED 60%, #6D28D9 100%);
$g-purple-banner:  linear-gradient(90deg, #1E1B4B 0%, #312E81 50%, #1E1B4B 100%);
$g-numbered-badge: linear-gradient(135deg, #8B5CF6 0%, #7C3AED 100%);

// -----------------------------------------------------------------------------
//  5. TYPOGRAPHY
// -----------------------------------------------------------------------------

$ff-base:    'Manrope', system-ui, -apple-system, sans-serif;
$ff-display: 'Plus Jakarta Sans', sans-serif;
// Scale (px-fixed scale for tight control)
$fz-2xs:       10px;          // + course-page
$fz-xs:        11px;
$fz-sm:        12px;
$fz-md:        14px;
$fz-base:      15px;
$fz-lg:        17px;
$fz-xl:        22px;
$fz-2xl:       26px;          // + course-page (course section titles)
$fz-3xl:       32px;
$fz-4xl:       38px;
$fz-5xl:       48px;          // + course-page
$fz-6xl:       54px;
$fz-7xl:       60px;          // + course-page (hero title)
$fz-display-1: 72px;          // + course-page (rank "#1")
$fw-medium:    500;
$fw-semibold:  600;
$fw-bold:      700;
$fw-black:     800;

// -----------------------------------------------------------------------------
//  6. RADII
// -----------------------------------------------------------------------------

$r-xs:   4px;
$r-sm:   8px;
$r-md:   12px;
$r-lg:   16px;
$r-xl:   20px;                // + course-page
$r-btn:  6px;
$r-pill: 999px;

// -----------------------------------------------------------------------------
//  7. SPACING (4px scale)
//  $s-22 preserved at 30px to match brand-file value (despite "22" naming).
// -----------------------------------------------------------------------------

$s-1:  4px;   $s-2:  8px;   $s-3: 12px;  $s-4: 16px;
$s-5:  20px;  $s-6:  24px;  $s-7: 28px;  $s-8: 32px;   // + course-page ($s-7)
$s-10: 40px;  $s-12: 48px;  $s-14: 56px; $s-16: 64px;
$s-20: 80px;                                            // + course-page
$s-22: 30px;                                            // brand-file value

// -----------------------------------------------------------------------------
//  8. SHADOWS
// -----------------------------------------------------------------------------

$sh-card:       0 1px 2px rgba(13,20,55,.04), 0 8px 24px rgba(13,20,55,.06);
$sh-card-hover: 0 2px 4px rgba(13,20,55,.05), 0 16px 36px rgba(13,20,55,.12);
$sh-card-soft:  0 1px 3px rgba(13,20,55,.05), 0 4px 12px rgba(13,20,55,.04);   // + course-page
$sh-btn-blue:   0 6px 22px rgba(37,99,235,.4);
$sh-btn-pink:   0 4px 18px rgba(255,45,135,.35);
$sh-btn-purple: 0 6px 20px rgba(124,58,237,.35);                               // + course-page
$sh-section:    0 1px 2px rgba(13,20,55,.03), 0 4px 16px rgba(13,20,55,.05);   // + course-page

// -----------------------------------------------------------------------------
//  9. LAYOUT
// -----------------------------------------------------------------------------

$wrap-max:         1280px;
$wrap-pad:         32px;
$wrap-pad-mobile:  20px;        // + course-page
$section-card-pad: 30px;        // + course-page
$hero-min-h:       640px;       // + course-page
$hero-h:           auto;

// -----------------------------------------------------------------------------
//  10. ACCESSIBILITY (Directive 8 — WCAG focus tokens)
// -----------------------------------------------------------------------------

$focus-ring-color:  $c-purple;
$focus-ring-width:  3px;
$focus-ring-offset: 2px;

// -----------------------------------------------------------------------------
//  11. BREAKPOINTS — Directive 7 mandates a $breakpoints MAP
// -----------------------------------------------------------------------------

$bp-sm: 480px;
$bp-md: 768px;
$bp-lg: 1024px;
$bp-xl: 1280px;

$breakpoints: (
  sm: $bp-sm,
  md: $bp-md,
  lg: $bp-lg,
  xl: $bp-xl
);

// -----------------------------------------------------------------------------
//  12. TRANSITIONS
// -----------------------------------------------------------------------------

$t-fast: .15s ease;
$t-base: .2s ease;
$t-slow: .3s ease;

// =============================================================================
//  GLOBAL MIXINS  (kept here so every page partial gets them via @use)
// =============================================================================

// Mobile-first
@mixin respond-up($bp) {
  $val: map-get($breakpoints, $bp);
  @if $val == null { $val: $bp; }
  @media (min-width: $val) { @content; }
}

// Desktop-first fallback (parity with brand-file mixin)
@mixin respond-below($bp) {
  $val: map-get($breakpoints, $bp);
  @if $val == null { $val: $bp; }
  @media (max-width: ($val - 1px)) { @content; }
}

@mixin display-text($size, $tracking: -.02em, $weight: $fw-black) {
  font-family: $ff-display;
  font-weight: $weight;
  font-size: $size;
  letter-spacing: $tracking;
  line-height: 1.04;
}

@mixin lift($shadow: $sh-card-hover) {
  transform: translateY(-3px);
  box-shadow: $shadow;
}

@mixin gradient-text($gradient) {
  background: $gradient;
  -webkit-background-clip: text;
          background-clip: text;
  color: transparent;
}

// WCAG 2.1 AA focus ring — used by EVERY interactive component
@mixin focus-ring($color: $focus-ring-color) {
  &:focus-visible {
    outline: $focus-ring-width solid $color;
    outline-offset: $focus-ring-offset;
    border-radius: $r-xs;
  }
}

// =============================================================================
//  BASE (Directive 9 — CMS-safe; NO global typography/list resets)
// =============================================================================

*, *::before, *::after { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
}

body {
  font-family: $ff-base;
  font-size: $fz-base;
  line-height: 1.5;
  color: $c-ink;
  background: $c-bg-softer;
  -webkit-font-smoothing: antialiased;
  text-wrap: pretty;
}

img {
  display: block;
  max-width: 100%;
  height: auto;
}

// =============================================================================
//  Shared layout primitive (kept global so every page can use it)
// =============================================================================

.wrap {
  max-width: $wrap-max;
  margin: 0 auto;
  padding: 0 $wrap-pad;
  @include respond-below(md) { padding: 0 $wrap-pad-mobile; }
}

