.brand {
  display: inline-block;
  line-height: 0;
  text-decoration: none;
}

.brand__mark {
  display: inline-block;
  background: #E5252B;
  color: #fff;
  padding: 8px 10px 7px;
  border-radius: 3px;
  text-align: center;
  line-height: 1;
  text-transform: uppercase;
}

.brand__name {
  display: block;
  font-family: "Plus Jakarta Sans", sans-serif;
  font-weight: 800;
  font-size: 18px;
  letter-spacing: .5px;
}

.brand__tag {
  display: block;
  margin-top: 4px;
  font-size: 5px;
  font-weight: 700;
  letter-spacing: .15px;
  line-height: 1.3;
}

.brand--mini:focus-visible {
  outline: 3px solid #7C3AED;
  outline-offset: 2px;
  border-radius: 4px;
}

.brand--footer:focus-visible {
  outline: 3px solid rgba(255, 255, 255, 0.6);
  outline-offset: 2px;
  border-radius: 4px;
}

.brand--footer .brand__name {
  font-size: 22px;
}

.brand--footer .brand__tag {
  font-size: 6px;
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 14px 22px;
  border: 1.5px solid transparent;
  border-radius: 6px;
  font-family: inherit;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: .2px;
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.2s ease, background 0.2s ease, border-color 0.2s ease, color 0.2s ease;
}

.button:focus-visible {
  outline: 3px solid #7C3AED;
  outline-offset: 2px;
  border-radius: 4px;
}

.button:hover {
  transform: translateY(-1px);
}

.button--primary-blue {
  background: linear-gradient(90deg, #2563EB, #1F5CFF);
  color: #fff;
  box-shadow: 0 6px 22px rgba(37, 99, 235, 0.4);
}

.button--primary-pink {
  background: linear-gradient(90deg, #FF2D87, #FF4FA1);
  color: #fff;
  box-shadow: 0 4px 18px rgba(255, 45, 135, 0.35);
  border-radius: 999px;
}

.button--primary-purple {
  background: linear-gradient(90deg, #8B5CF6 0%, #7C3AED 100%);
  color: #fff;
  box-shadow: 0 6px 20px rgba(124, 58, 237, 0.35);
}

.button--primary-dark {
  background: #0A1230;
  color: #fff;
  border-color: rgba(255, 255, 255, 0.18);
}

.button--primary-light {
  background: #fff;
  color: #0B1020;
}

.button--secondary-light {
  background: transparent;
  color: #fff;
  border-color: rgba(255, 255, 255, 0.55);
}

.button--secondary-light:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: #fff;
}

.button--secondary-blue {
  background: transparent;
  color: #1F5CFF;
  border-color: #1F5CFF;
}

.button--ghost-dark {
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
  border-color: rgba(255, 255, 255, 0.18);
  border-radius: 999px;
}

.topbar {
  position: relative;
  z-index: 5;
  padding: 18px 40px;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 32px;
  max-width: 1280px;
  margin: 0 auto;
}

.topbar__nav {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 36px;
  font-size: 14px;
  font-weight: 500;
}

.topbar__nav-item {
  /* hook */
}

.topbar__nav-link {
  color: #fff;
  text-decoration: none;
  opacity: .92;
  transition: opacity 0.15s ease, color 0.15s ease;
}

.topbar__nav-link:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
  border-radius: 4px;
}

.topbar__nav-link:hover {
  opacity: 1;
  color: #B8C7FF;
}

.topbar__actions {
  display: flex;
  align-items: center;
  gap: 14px;
}

.topbar__icon-btn {
  width: 36px;
  height: 36px;
  display: inline-grid;
  place-items: center;
  background: transparent;
  border: 0;
  border-radius: 999px;
  color: #fff;
  opacity: .8;
  cursor: pointer;
  font: inherit;
}

.topbar__icon-btn:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
  border-radius: 4px;
}

@media (max-width: 1023px) {
  .topbar {
    grid-template-columns: auto auto;
    gap: 16px;
    padding: 16px 20px;
  }
  .topbar__nav {
    display: none;
  }
  .topbar__actions {
    justify-self: end;
  }
}

@media (max-width: 479px) {
  .topbar__actions .button {
    padding: 10px 14px;
    font-size: 12px;
  }
}

